/**
 * Native form submission helper
 *
 * Replaces the legacy bundled form plugin. FormData preserves file uploads and
 * successful form controls when a form is sent with fetch().
 */

export default class AjaxForm {
    constructor(form) {
        if (!(form instanceof HTMLFormElement)) {
            throw new TypeError("AjaxForm requires an HTMLFormElement.");
        }
        this.form = form;
    }

    createFormData(parameters = {}, submitter = null) {
        try {
            const isSubmitButton = submitter instanceof HTMLButtonElement
                && (submitter.type === "submit" || submitter.type === "image")
                || submitter instanceof HTMLInputElement
                    && ["submit", "image"].includes(submitter.type);
            const formData = isSubmitButton && submitter.name
                ? new FormData(this.form, submitter)
                : new FormData(this.form);

            // Request parameters take precedence over fields with the same name.
            for (const [name, value] of Object.entries(parameters)) {
                if (name === "href" || name === "requestType" || value === undefined || value === null) {
                    continue;
                }
                formData.delete(name);
                if (Array.isArray(value)) {
                    for (const item of value) {
                        formData.append(name, String(item));
                    }
                } else {
                    formData.append(name, String(value));
                }
            }
            return formData;
        } catch (error) {
            console.error("AjaxForm: unable to serialize form.", error);
            throw error;
        }
    }

    serializeArray() {
        return Array.from(this.createFormData().entries(), ([name, value]) => ({name, value}));
    }
}
